  /**
   * @method
   * @name xt#cancelOrder
   * @description cancels an open order
   * @see https://doc.xt.com/docs/spot/Order/CancelOrder
   * @see https://doc.xt.com/docs/futures/Order/cancel-orders
   * @see https://doc.xt.com/docs/futures/Entrust/CancelTriggerOrders
   * @see https://doc.xt.com/docs/futures/Entrust/CancelStopLimit
   * @see https://doc.xt.com/docs/futures/Entrust/CancelSingleTrack
   * @param {string} id order id
   * @param {string} [symbol] unified symbol of the market the order was made in
   * @param {object} params extra parameters specific to the exchange API
   * endpoint
   * @param {bool} [params.trigger] if the order is a trigger order or not
   * @param {bool} [params.stopLossTakeProfit] if the order is a stop-loss or
   * take-profit order
   * @param {bool} [params.trailing] if the order is a trailing order or not
   * @returns {object} An [order structure]{@link
   * https://docs.ccxt.com/en/latest/manual.html#order-structure}
   */
  std::shared_future<ccxt::any>
  cancelOrder(ccxt::any id, ccxt::any symbol = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::
        async(std::launch::deferred,
              [=]() mutable -> ccxt::any {
                if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                  awaitValue(this->loadMarkets());
                }
                ccxt::any market = ccxt::any{};
                if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                  market = this->market(symbol);
                }
                ccxt::any request = ccxt::dict{};
                ccxt::any type = ccxt::any{};
                ccxt::any subType = ccxt::any{};
                ccxt::any response = ccxt::any{};
                ccxt::any typeparamsVariable = this->handleMarketTypeAndParams(
                    std::string("cancelOrder"), market, params);
                type = ::getValue(typeparamsVariable, 0);
                params = ::getValue(typeparamsVariable, 1);
                ccxt::any subTypeparamsVariable = this->handleSubTypeAndParams(
                    std::string("cancelOrder"), market, params);
                subType = ::getValue(subTypeparamsVariable, 0);
                params = ::getValue(subTypeparamsVariable, 1);
                ccxt::any trigger = this->safeBool2(
                    params, std::string("trigger"), std::string("stop"));
                ccxt::any stopLossTakeProfit =
                    this->safeBool(params, std::string("stopLossTakeProfit"));
                ccxt::any trailing =
                    this->safeBool(params, std::string("trailing"));
                if (isTrue(isEqual(trailing, true))) {
                  ccxt::any isContract =
                      isTrue(isTrue((!isEqual(subType, ccxt::any{}))) ||
                             isTrue((isEqual(type, std::string("swap"))))) ||
                      isTrue((isEqual(type, std::string("future"))));
                  if (!isTrue(isContract)) {
                    throw NotSupported(toString(add(
                        this->id,
                        std::string(" cancelOrder() trailing orders are only "
                                    "supported on swap and future markets"))));
                  }
                }
                if (isTrue(isEqual(trigger, true))) {
                  ::setValue(request, std::string("entrustId"), id);
                } else if (isTrue(isEqual(stopLossTakeProfit, true))) {
                  ::setValue(request, std::string("profitId"), id);
                } else if (isTrue(isEqual(trailing, true))) {
                  ::setValue(request, std::string("trackId"), id);
                } else {
                  ::setValue(request, std::string("orderId"), id);
                }
                if (isTrue(isEqual(trigger, true))) {
                  params = this->omit(params, ccxt::list{std::string("trigger"),
                                                         std::string("stop")});
                  if (isTrue(isEqual(subType, std::string("inverse")))) {
                    response = awaitValue(
                        this->privateInversePostFutureTradeV1EntrustCancelPlan(
                            this->extend(request, params)));
                  } else {
                    response = awaitValue(
                        this->privateLinearPostFutureTradeV1EntrustCancelPlan(
                            this->extend(request, params)));
                  }
                } else if (isTrue(isEqual(stopLossTakeProfit, true))) {
                  params =
                      this->omit(params, std::string("stopLossTakeProfit"));
                  if (isTrue(isEqual(subType, std::string("inverse")))) {
                    response = awaitValue(
                        this->privateInversePostFutureTradeV1EntrustCancelProfitStop(
                            this->extend(request, params)));
                  } else {
                    response = awaitValue(
                        this->privateLinearPostFutureTradeV1EntrustCancelProfitStop(
                            this->extend(request, params)));
                  }
                } else if (isTrue(isEqual(trailing, true))) {
                  params = this->omit(params, std::string("trailing"));
                  if (isTrue(isEqual(subType, std::string("inverse")))) {
                    response = awaitValue(
                        this->privateInversePostFutureTradeV1EntrustCancelTrack(
                            this->extend(request, params)));
                  } else {
                    response = awaitValue(
                        this->privateLinearPostFutureTradeV1EntrustCancelTrack(
                            this->extend(request, params)));
                  }
                } else if (isTrue(isEqual(subType, std::string("inverse")))) {
                  response = awaitValue(
                      this->privateInversePostFutureTradeV1OrderCancel(
                          this->extend(request, params)));
                } else if (isTrue(
                               isTrue(isTrue((isEqual(
                                          subType, std::string("linear")))) ||
                                      isTrue((isEqual(type,
                                                      std::string("swap"))))) ||
                               isTrue(
                                   (isEqual(type, std::string("future")))))) {
                  response = awaitValue(
                      this->privateLinearPostFutureTradeV1OrderCancel(
                          this->extend(request, params)));
                } else {
                  response = awaitValue(this->privateSpotDeleteOrderOrderId(
                      this->extend(request, params)));
                }
                //
                // spot
                //
                //     {
                //         "rc": 0,
                //         "mc": "SUCCESS",
                //         "ma": [],
                //         "result": {
                //             "cancelId": "208322474307982720"
                //         }
                //     }
                //
                // swap and future
                //
                //     {
                //         "returnCode": 0,
                //         "msgInfo": "success",
                //         "error": null,
                //         "result": "208319789679471616"
                //     }
                //
                ccxt::any isContractResponse =
                    (isTrue(isTrue((!isEqual(subType, ccxt::any{}))) ||
                            isTrue((isEqual(type, std::string("swap"))))) ||
                     isTrue((isEqual(type, std::string("future")))));
                ccxt::any order =
                    (isTrue(isContractResponse)
                         ? ccxt::any(response)
                         : ccxt::any(this->safeDict(
                               response, std::string("result"), ccxt::dict{})));
                return this->parseOrder(order, market);
              })
            .share();
  }

  /**
   * @method
   * @name xt#cancelAllOrders
   * @description cancel all open orders in a market
   * @see https://doc.xt.com/docs/spot/Order/CancelCurrentPendingOrder
   * @see https://doc.xt.com/docs/futures/Order/cancel-all-orders
   * @see https://doc.xt.com/docs/futures/Entrust/CancelAllTriggerOrders
   * @see https://doc.xt.com/docs/futures/Entrust/CancelAllStopLimit
   * @see https://doc.xt.com/docs/futures/Entrust/CancelAllTrack
   * @param {string} [symbol] unified market symbol of the market to cancel
   * orders in
   * @param {object} params extra parameters specific to the exchange API
   * endpoint
   * @param {bool} [params.trigger] if the order is a trigger order or not
   * @param {bool} [params.stopLossTakeProfit] if the order is a stop-loss or
   * take-profit order
   * @param {bool} [params.trailing] if the orders are trailing orders or not
   * @returns {object[]} a list of [order structures]{@link
   * https://docs.ccxt.com/en/latest/manual.html#order-structure}
   */
  std::shared_future<ccxt::any>
  cancelAllOrders(ccxt::any symbol = ccxt::any{},
                  ccxt::any params = ccxt::dict{}) override {
    return std::
        async(std::launch::deferred,
              [=]() mutable -> ccxt::any {
                if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                  awaitValue(this->loadMarkets());
                }
                ccxt::any request = ccxt::dict{};
                ccxt::any market = ccxt::any{};
                if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                  market = this->market(symbol);
                  ::setValue(request, std::string("symbol"),
                             ::getValue(market, std::string("id")));
                }
                ccxt::any type = ccxt::any{};
                ccxt::any subType = ccxt::any{};
                ccxt::any response = ccxt::any{};
                ccxt::any typeparamsVariable = this->handleMarketTypeAndParams(
                    std::string("cancelAllOrders"), market, params);
                type = ::getValue(typeparamsVariable, 0);
                params = ::getValue(typeparamsVariable, 1);
                ccxt::any subTypeparamsVariable = this->handleSubTypeAndParams(
                    std::string("cancelAllOrders"), market, params);
                subType = ::getValue(subTypeparamsVariable, 0);
                params = ::getValue(subTypeparamsVariable, 1);
                ccxt::any trigger = this->safeBool2(
                    params, std::string("trigger"), std::string("stop"));
                ccxt::any stopLossTakeProfit =
                    this->safeBool(params, std::string("stopLossTakeProfit"));
                ccxt::any trailing =
                    this->safeBool(params, std::string("trailing"));
                if (isTrue(isEqual(trailing, true))) {
                  ccxt::any isContract =
                      isTrue(isTrue((!isEqual(subType, ccxt::any{}))) ||
                             isTrue((isEqual(type, std::string("swap"))))) ||
                      isTrue((isEqual(type, std::string("future"))));
                  if (!isTrue(isContract)) {
                    throw NotSupported(toString(
                        add(this->id,
                            std::string(
                                " cancelAllOrders() trailing orders are only "
                                "supported on swap and future markets"))));
                  }
                }
                if (isTrue(isEqual(trigger, true))) {
                  params = this->omit(params, ccxt::list{std::string("trigger"),
                                                         std::string("stop")});
                  if (isTrue(isEqual(subType, std::string("inverse")))) {
                    response = awaitValue(
                        this->privateInversePostFutureTradeV1EntrustCancelAllPlan(
                            this->extend(request, params)));
                  } else {
                    response = awaitValue(
                        this->privateLinearPostFutureTradeV1EntrustCancelAllPlan(
                            this->extend(request, params)));
                  }
                } else if (isTrue(isEqual(stopLossTakeProfit, true))) {
                  params =
                      this->omit(params, std::string("stopLossTakeProfit"));
                  if (isTrue(isEqual(subType, std::string("inverse")))) {
                    response = awaitValue(
                        this->privateInversePostFutureTradeV1EntrustCancelAllProfitStop(
                            this->extend(request, params)));
                  } else {
                    response = awaitValue(
                        this->privateLinearPostFutureTradeV1EntrustCancelAllProfitStop(
                            this->extend(request, params)));
                  }
                } else if (isTrue(isEqual(trailing, true))) {
                  params = this->omit(params, std::string("trailing"));
                  if (isTrue(isEqual(subType, std::string("inverse")))) {
                    response = awaitValue(
                        this->privateInversePostFutureTradeV1EntrustCancelAllTrack(
                            this->extend(request, params)));
                  } else {
                    response = awaitValue(
                        this->privateLinearPostFutureTradeV1EntrustCancelAllTrack(
                            this->extend(request, params)));
                  }
                } else if (isTrue(isEqual(subType, std::string("inverse")))) {
                  response = awaitValue(
                      this->privateInversePostFutureTradeV1OrderCancelAll(
                          this->extend(request, params)));
                } else if (isTrue(
                               isTrue(isTrue((isEqual(
                                          subType, std::string("linear")))) ||
                                      isTrue((isEqual(type,
                                                      std::string("swap"))))) ||
                               isTrue(
                                   (isEqual(type, std::string("future")))))) {
                  response = awaitValue(
                      this->privateLinearPostFutureTradeV1OrderCancelAll(
                          this->extend(request, params)));
                } else {
                  ccxt::any marginMode = ccxt::any{};
                  ccxt::any marginModeparamsVariable =
                      this->handleMarginModeAndParams(
                          std::string("cancelAllOrders"), params);
                  marginMode = ::getValue(marginModeparamsVariable, 0);
                  params = ::getValue(marginModeparamsVariable, 1);
                  ccxt::any marginOrSpotRequest =
                      (isTrue((!isEqual(marginMode, ccxt::any{})))
                           ? ccxt::any(std::string("LEVER"))
                           : ccxt::any(std::string("SPOT")));
                  ::setValue(request, std::string("bizType"),
                             marginOrSpotRequest);
                  response = awaitValue(this->privateSpotDeleteOpenOrder(
                      this->extend(request, params)));
                }
                //
                // spot and margin
                //
                //     {
                //         "rc": 0,
                //         "mc": "SUCCESS",
                //         "ma": [],
                //         "result": null
                //     }
                //
                // swap and future
                //
                //     {
                //         "returnCode": 0,
                //         "msgInfo": "success",
                //         "error": null,
                //         "result": true
                //     }
                //
                return ccxt::list{this->safeOrder(response)};
              })
            .share();
  }

  /**
   * @method
   * @name xt#cancelOrders
   * @description cancel multiple orders
   * @see https://doc.xt.com/docs/spot/Order/CancelBatchOrder
   * @param {string[]} ids order ids
   * @param {string} [symbol] unified market symbol of the market to cancel
   * orders in
   * @param {object} params extra parameters specific to the exchange API
   * endpoint
   * @returns {object[]} a list of [order structures]{@link
   * https://docs.ccxt.com/en/latest/manual.html#order-structure}
   */
  std::shared_future<ccxt::any>
  cancelOrders(ccxt::any ids, ccxt::any symbol = ccxt::any{},
               ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any request = ccxt::dict{
                     {std::string("orderIds"), ids},
                 };
                 ccxt::any market = ccxt::any{};
                 if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                   market = this->market(symbol);
                 }
                 ccxt::any subType = ccxt::any{};
                 ccxt::any subTypeparamsVariable = this->handleSubTypeAndParams(
                     std::string("cancelOrders"), market, params);
                 subType = ::getValue(subTypeparamsVariable, 0);
                 params = ::getValue(subTypeparamsVariable, 1);
                 if (isTrue(!isEqual(subType, ccxt::any{}))) {
                   throw NotSupported(toString(add(
                       this->id,
                       std::string(
                           " cancelOrders() does not support swap and future "
                           "orders, only spot orders are accepted"))));
                 }
                 ccxt::any response =
                     awaitValue(this->privateSpotDeleteBatchOrder(
                         this->extend(request, params)));
                 //
                 // spot
                 //
                 //     {
                 //         "rc": 0,
                 //         "mc": "SUCCESS",
                 //         "ma": [],
                 //         "result": null
                 //     }
                 //
                 return ccxt::list{this->safeOrder(response)};
               })
        .share();
  }

  ccxt::any parseOrder(ccxt::any order,
                       ccxt::any market = ccxt::any{}) override {
    //
    // spot: createOrder
    //
    //     {
    //         "orderId": "204371980095156544"
    //     }
    //
    // spot: cancelOrder
    //
    //     {
    //         "cancelId": "208322474307982720"
    //     }
    //
    // swap and future: createOrder, cancelOrder, editOrder
    //
    //     {
    //         "returnCode": 0,
    //         "msgInfo": "success",
    //         "error": null,
    //         "result": "206410760006650176"
    //     }
    //
    // spot: fetchOrder, fetchOrders, fetchOpenOrders, fetchClosedOrders,
    // fetchCanceledOrders, fetchOrdersByStatus
    //
    //     {
    //         "symbol": "btc_usdt",
    //         "orderId": "207505997850909952",
    //         "clientOrderId": null,
    //         "baseCurrency": "btc",
    //         "quoteCurrency": "usdt",
    //         "side": "BUY",
    //         "type": "LIMIT",
    //         "timeInForce": "GTC",
    //         "price": "20000.00",
    //         "origQty": "0.001000",
    //         "origQuoteQty": "20.00",
    //         "executedQty": "0.000000",
    //         "leavingQty": "0.001000",
    //         "tradeBase": "0.000000",
    //         "tradeQuote": "0.00",
    //         "avgPrice": null,
    //         "fee": null,
    //         "feeCurrency": null,
    //         "closed": false,
    //         "state": "NEW",
    //         "time": 1679175285162,
    //         "updatedTime": 1679175285255
    //     }
    //
    // swap and future: fetchOrder, fetchOrders, fetchOpenOrders,
    // fetchClosedOrders, fetchCanceledOrders, fetchOrdersByStatus
    //
    //     {
    //         "orderId": "207519546930995456",
    //         "clientOrderId": null,
    //         "symbol": "btc_usdt",
    //         "orderType": "LIMIT",
    //         "orderSide": "BUY",
    //         "positionSide": "LONG",
    //         "timeInForce": "GTC",
    //         "closePosition": false,
    //         "price": "20000",
    //         "origQty": "100",
    //         "avgPrice": "0",
    //         "executedQty": "0",
    //         "marginFrozen": "4.12",
    //         "remark": null,
    //         "triggerProfitPrice": null,
    //         "triggerStopPrice": null,
    //         "sourceId": null,
    //         "sourceType": "DEFAULT",
    //         "forceClose": false,
    //         "closeProfit": null,
    //         "state": "CANCELED",
    //         "createdTime": 1679178515689,
    //         "updatedTime": 1679180096172
    //     }
    //
    // trigger: fetchOrder, fetchOrders, fetchOpenOrders, fetchClosedOrders,
    // fetchCanceledOrders, fetchOrdersByStatus
    //
    //     {
    //         "entrustId": "216300248132756992",
    //         "symbol": "btc_usdt",
    //         "entrustType": "STOP",
    //         "orderSide": "SELL",
    //         "positionSide": "SHORT",
    //         "timeInForce": "GTC",
    //         "closePosition": null,
    //         "price": "20000",
    //         "origQty": "1",
    //         "stopPrice": "19000",
    //         "triggerPriceType": "LATEST_PRICE",
    //         "state": "NOT_TRIGGERED",
    //         "marketOrderLevel": null,
    //         "createdTime": 1681271998064,
    //         "updatedTime": 1681271998064,
    //         "ordinary": false
    //     }
    //
    // stop-loss and take-profit: fetchOrder, fetchOpenOrders,
    // fetchClosedOrders, fetchCanceledOrders, fetchOrdersByStatus
    //
    //     {
    //         "profitId": "216306213226230400",
    //         "symbol": "btc_usdt",
    //         "positionSide": "LONG",
    //         "origQty": "1",
    //         "triggerPriceType": "LATEST_PRICE",
    //         "triggerProfitPrice": null,
    //         "triggerStopPrice": "20000",
    //         "entryPrice": null,
    //         "positionSize": null,
    //         "isolatedMargin": null,
    //         "executedQty": null,
    //         "avgPrice": null,
    //         "positionType": "ISOLATED",
    //         "state": "NOT_TRIGGERED",
    //         "createdTime": 1681273420039
    //     }
    //
    // spot editOrder
    //
    //     {
    //         "orderId": "484203027161892224",
    //         "modifyId": "484203544105344000",
    //         "clientModifyId": null
    //     }
    //
    ccxt::any marketId = this->safeString(order, std::string("symbol"));
    ccxt::any marketType =
        (isTrue(isTrue((inOp(order, std::string("result")))) ||
                isTrue((inOp(order, std::string("positionSide")))))
             ? ccxt::any(std::string("contract"))
             : ccxt::any(std::string("spot")));
    market = this->safeMarket(marketId, market, ccxt::any{}, marketType);
    ccxt::any symbol =
        this->safeSymbol(marketId, market, ccxt::any{}, marketType);
    ccxt::any timestamp = this->safeInteger2(order, std::string("time"),
                                             std::string("createdTime"));
    ccxt::any quantity = this->safeNumber(order, std::string("origQty"));
    ccxt::any amount = (isTrue((isEqual(marketType, std::string("spot"))))
                            ? ccxt::any(quantity)
                            : ccxt::any(ccxt::Precise::stringMul(
                                  this->numberToString(quantity),
                                  this->numberToString(::getValue(
                                      market, std::string("contractSize"))))));
    ccxt::any filledQuantity =
        this->safeNumber(order, std::string("executedQty"));
    ccxt::any filled = (isTrue((isEqual(marketType, std::string("spot"))))
                            ? ccxt::any(filledQuantity)
                            : ccxt::any(ccxt::Precise::stringMul(
                                  this->numberToString(filledQuantity),
                                  this->numberToString(::getValue(
                                      market, std::string("contractSize"))))));
    ccxt::any lastUpdatedTimestamp =
        this->safeInteger(order, std::string("updatedTime"));
    ccxt::any timeInForce = this->safeString(order, std::string("timeInForce"));
    ccxt::any postOnly = ccxt::any{};
    if (isTrue(!isEqual(timeInForce, ccxt::any{}))) {
      if (isTrue(isEqual(timeInForce, std::string("GTX")))) {
        // GTX means "Good Till Crossing" and is an equivalent way of saying
        // Post Only
        timeInForce = std::string("PO");
      }
      postOnly = (isEqual(timeInForce, std::string("PO")));
    }
    ccxt::any side = this->safeStringLower2(order, std::string("side"),
                                            std::string("orderSide"));
    if (isTrue(isEqual(side, ccxt::any{}))) {
      // the stop loss and take profit entries carry only the position
      // side, they close the position, so a long position closes with a
      // sell and a short position closes with a buy
      // see https://github.com/ccxt/ccxt/issues/25288
      ccxt::any positionSide =
          this->safeString(order, std::string("positionSide"));
      if (isTrue(!isEqual(positionSide, ccxt::any{}))) {
        if (isTrue(isEqual(positionSide, std::string("LONG")))) {
          side = std::string("sell");
        } else {
          side = std::string("buy");
        }
      }
    }
    return this->safeOrder(
        ccxt::dict{
            {std::string("info"), order},
            {std::string("id"),
             this->safeStringN(
                 order,
                 ccxt::list{std::string("orderId"), std::string("result"),
                            std::string("cancelId"), std::string("entrustId"),
                            std::string("profitId"), std::string("trackId")})},
            {std::string("clientOrderId"),
             this->safeString2(order, std::string("clientOrderId"),
                               std::string("clientModifyId"))},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("lastTradeTimestamp"), lastUpdatedTimestamp},
            {std::string("lastUpdateTimestamp"), lastUpdatedTimestamp},
            {std::string("symbol"), symbol},
            {std::string("type"),
             this->safeStringLower2(order, std::string("type"),
                                    std::string("orderType"))},
            {std::string("timeInForce"), timeInForce},
            {std::string("postOnly"), postOnly},
            {std::string("side"), side},
            {std::string("price"),
             this->safeNumber(order, std::string("price"))},
            {std::string("triggerPrice"),
             this->safeNumber(order, std::string("stopPrice"))},
            {std::string("stopLoss"),
             this->safeNumber(order, std::string("triggerStopPrice"))},
            {std::string("takeProfit"),
             this->safeNumber(order, std::string("triggerProfitPrice"))},
            {std::string("amount"), amount},
            {std::string("filled"), filled},
            {std::string("remaining"),
             this->safeNumber(order, std::string("leavingQty"))},
            {std::string("cost"), ccxt::any{}},
            {std::string("average"),
             this->safeNumber(order, std::string("avgPrice"))},
            {std::string("status"), this->parseOrderStatus(this->safeString(
                                        order, std::string("state")))},
            {std::string("fee"),
             ccxt::dict{
                 {std::string("currency"),
                  this->safeCurrencyCode(
                      this->safeString(order, std::string("feeCurrency")))},
                 {std::string("cost"),
                  this->safeNumber(order, std::string("fee"))},
             }},
            {std::string("trades"), ccxt::any{}},
        },
        market);
  }

  virtual ccxt::any parseOrderStatus(ccxt::any status) {
    ccxt::any statuses = ccxt::dict{
        {std::string("NEW"), std::string("open")},
        {std::string("PARTIALLY_FILLED"), std::string("open")},
        {std::string("FILLED"), std::string("closed")},
        {std::string("CANCELED"), std::string("canceled")},
        {std::string("REJECTED"), std::string("rejected")},
        {std::string("EXPIRED"), std::string("expired")},
        {std::string("UNFINISHED"), std::string("open")},
        {std::string("NOT_ACTIVATION"), std::string("open")},
        {std::string("NOT_TRIGGERED"), std::string("open")},
        {std::string("TRIGGERING"), std::string("open")},
        {std::string("TRIGGERED"), std::string("closed")},
        {std::string("USER_REVOCATION"), std::string("canceled")},
        {std::string("PLATFORM_REVOCATION"), std::string("rejected")},
        {std::string("DELEGATION_FAILED"), std::string("rejected")},
        {std::string("HISTORY"), std::string("expired")},
    };
    return this->safeString(statuses, status, status);
  }

  /**
   * @method
   * @name xt#fetchLedger
   * @description fetch the history of changes, actions done by the user or
   * operations that altered the balance of the user
   * @see
   * https://doc.xt.com/docs/futures/User/Get%20User's%20Account%20Flow%20Information
   * @param {string} [code] unified currency code
   * @param {int} [since] timestamp in ms of the earliest ledger entry
   * @param {int} [limit] max number of ledger entries to return
   * @param {object} params extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [ledger structure]{@link
   * https://docs.ccxt.com/en/latest/manual.html#ledger-structure}
   */
  std::shared_future<ccxt::any>
  fetchLedger(ccxt::any code = ccxt::any{}, ccxt::any since = ccxt::any{},
              ccxt::any limit = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any request = ccxt::dict{};
                 ccxt::any currency = ccxt::any{};
                 if (isTrue(!isEqual(code, ccxt::any{}))) {
                   currency = this->currency(code);
                 }
                 if (isTrue(!isEqual(since, ccxt::any{}))) {
                   ::setValue(request, std::string("startTime"), since);
                 }
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("limit"), limit);
                 }
                 ccxt::any type = ccxt::any{};
                 ccxt::any subType = ccxt::any{};
                 ccxt::any response = ccxt::any{};
                 ccxt::any typeparamsVariable = this->handleMarketTypeAndParams(
                     std::string("fetchLedger"), ccxt::any{}, params);
                 type = ::getValue(typeparamsVariable, 0);
                 params = ::getValue(typeparamsVariable, 1);
                 ccxt::any subTypeparamsVariable = this->handleSubTypeAndParams(
                     std::string("fetchLedger"), ccxt::any{}, params);
                 subType = ::getValue(subTypeparamsVariable, 0);
                 params = ::getValue(subTypeparamsVariable, 1);
                 if (isTrue(isEqual(subType, std::string("inverse")))) {
                   response = awaitValue(
                       this->privateInverseGetFutureUserV1BalanceBills(
                           this->extend(request, params)));
                 } else if (isTrue(
                                isTrue(isTrue((isEqual(
                                           subType, std::string("linear")))) ||
                                       isTrue((isEqual(
                                           type, std::string("swap"))))) ||
                                isTrue(
                                    (isEqual(type, std::string("future")))))) {
                   response = awaitValue(
                       this->privateLinearGetFutureUserV1BalanceBills(
                           this->extend(request, params)));
                 } else {
                   throw NotSupported(toString(
                       add(this->id,
                           std::string(" fetchLedger() does not support spot "
                                       "transactions, only swap and future "
                                       "wallet transactions are supported"))));
                 }
                 //
                 //     {
                 //         "returnCode": 0,
                 //         "msgInfo": "success",
                 //         "error": null,
                 //         "result": {
                 //             "hasPrev": false,
                 //             "hasNext": false,
                 //             "items": [
                 //                 {
                 //                     "id": "207260567109387525",
                 //                     "coin": "usdt",
                 //                     "symbol": "btc_usdt",
                 //                     "type": "FEE",
                 //                     "amount": "-0.0213",
                 //                     "side": "SUB",
                 //                     "afterAmount": null,
                 //                     "createdTime": 1679116769914
                 //                 },
                 //             ]
                 //         }
                 //     }
                 //
                 ccxt::any data = this->safeDict(
                     response, std::string("result"), ccxt::dict{});
                 ccxt::any ledger =
                     this->safeList(data, std::string("items"), ccxt::list{});
                 return this->parseLedger(ledger, currency, since, limit);
               })
        .share();
  }

  ccxt::any parseLedgerEntry(ccxt::any item,
                             ccxt::any currency = ccxt::any{}) override {
    //
    //     {
    //         "id": "207260567109387524",
    //         "coin": "usdt",
    //         "symbol": "btc_usdt",
    //         "type": "FEE",
    //         "amount": "-0.0213",
    //         "side": "SUB",
    //         "afterAmount": null,
    //         "createdTime": 1679116769914
    //     }
    //
    ccxt::any side = this->safeString(item, std::string("side"));
    ccxt::any direction = (isTrue((isEqual(side, std::string("ADD"))))
                               ? ccxt::any(std::string("in"))
                               : ccxt::any(std::string("out")));
    ccxt::any currencyId = this->safeString(item, std::string("coin"));
    currency = this->safeCurrency(currencyId, currency);
    ccxt::any timestamp = this->safeInteger(item, std::string("createdTime"));
    return this->safeLedgerEntry(
        ccxt::dict{
            {std::string("info"), item},
            {std::string("id"), this->safeString(item, std::string("id"))},
            {std::string("direction"), direction},
            {std::string("account"), ccxt::any{}},
            {std::string("referenceId"), ccxt::any{}},
            {std::string("referenceAccount"), ccxt::any{}},
            {std::string("type"), this->parseLedgerEntryType(this->safeString(
                                      item, std::string("type")))},
            {std::string("currency"),
             this->safeCurrencyCode(currencyId, currency)},
            {std::string("amount"),
             this->safeNumber(item, std::string("amount"))},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("before"), ccxt::any{}},
            {std::string("after"),
             this->safeNumber(item, std::string("afterAmount"))},
            {std::string("status"), ccxt::any{}},
            {std::string("fee"),
             ccxt::dict{
                 {std::string("currency"), ccxt::any{}},
                 {std::string("cost"), ccxt::any{}},
             }},
        },
        currency);
  }

  virtual ccxt::any parseLedgerEntryType(ccxt::any type) {
    ccxt::any ledgerType = ccxt::dict{
        {std::string("EXCHANGE"), std::string("transfer")},
        {std::string("CLOSE_POSITION"), std::string("trade")},
        {std::string("TAKE_OVER"), std::string("trade")},
        {std::string("MERGE"), std::string("trade")},
        {std::string("QIANG_PING_MANAGER"), std::string("fee")},
        {std::string("FUND"), std::string("fee")},
        {std::string("FEE"), std::string("fee")},
        {std::string("ADL"), std::string("auto-deleveraging")},
    };
    return this->safeString(ledgerType, type, type);
  }

  /**
   * @method
   * @name xt#fetchDepositAddress
   * @description fetch the deposit address for a currency associated with this
   * account
   * @see https://doc.xt.com/docs/spot/Deposit&Withdrawal/GetDepositAddress
   * @param {string} code unified currency code
   * @param {object} params extra parameters specific to the exchange API
   * endpoint
   * @param {string} params.network required network id
   * @returns {object} an [address structure]{@link
   * https://docs.ccxt.com/en/latest/manual.html#address-structure}
   */
  std::shared_future<ccxt::any>
  fetchDepositAddress(ccxt::any code,
                      ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any networkCode = ccxt::any{};
                 ccxt::any networkCodeparamsVariable =
                     this->handleNetworkCodeAndParams(params);
                 networkCode = ::getValue(networkCodeparamsVariable, 0);
                 params = ::getValue(networkCodeparamsVariable, 1);
                 ccxt::any currency = this->currency(code);
                 ccxt::any networkId = this->networkCodeToId(networkCode, code);
                 this->checkRequiredArgument(std::string("fetchDepositAddress"),
                                             networkId, std::string("network"));
                 ccxt::any request = ccxt::dict{
                     {std::string("currency"),
                      ::getValue(currency, std::string("id"))},
                     {std::string("chain"), networkId},
                 };
                 ccxt::any response =
                     awaitValue(this->privateSpotGetDepositAddress(
                         this->extend(request, params)));
                 //
                 //     {
                 //         "rc": 0,
                 //         "mc": "SUCCESS",
                 //         "ma": [],
                 //         "result": {
                 //             "address":
                 //             "0x7f7173cf29d3846d20ca5a3aec1120b93dbd157a",
                 //             "memo": ""
                 //         }
                 //     }
                 //
                 ccxt::any result = this->safeDict(
                     response, std::string("result"), ccxt::dict{});
                 return this->parseDepositAddress(result, currency);
               })
        .share();
  }

  ccxt::any parseDepositAddress(ccxt::any depositAddress,
                                ccxt::any currency = ccxt::any{}) override {
    //
    //     {
    //         "address": "0x7f7173cf29d3846d20ca5a3aec1120b93dbd157a",
    //         "memo": ""
    //     }
    //
    ccxt::any address =
        this->safeString(depositAddress, std::string("address"));
    this->checkAddress(address);
    return ccxt::dict{
        {std::string("info"), depositAddress},
        {std::string("currency"),
         this->safeCurrencyCode(ccxt::any{}, currency)},
        {std::string("network"), ccxt::any{}},
        {std::string("address"), address},
        {std::string("tag"),
         this->safeString(depositAddress, std::string("memo"))},
    };
  }

